/**
 * Apple Root CA - G3 — the root every App Store signed payload (StoreKit 2 transaction,
 * renewal info, App Store Server Notification V2) chains to. Embedded rather than read
 * from disk so the server bundle needs no file asset. Downloaded from
 * https://www.apple.com/certificateauthority/AppleRootCA-G3.cer; its SHA-256 fingerprint
 * is pinned by the test, so a changed byte fails CI rather than widening trust.
 *
 * SHA-256: 63:34:3A:BF:B8:9A:6A:03:EB:B5:7E:9B:3F:5F:A7:BE:7C:4F:5C:75:6F:30:17:B3:A8:C4:88:C3:65:3E:91:79
 * Valid until 2039-04-30.
 */
export const APPLE_ROOT_CA_G3_DER_BASE64 =
  '';

export const APPLE_ROOT_CA_G3_SHA256 =
  '63343ABFB89A6A03EBB57E9B3F5FA7BE7C4F5C756F3017B3A8C488C3653E9179';

/** The DER bytes of every root this server trusts for App Store signatures. */
export function appleRootCertificates(): Buffer[] {
  return [Buffer.from(APPLE_ROOT_CA_G3_DER_BASE64, 'base64')];
}
